style.css:
@-moz-document domain("chatgpt.com"), domain("chatgpt.com") {
:root{
--pink-bg: #fff0f6;       /* fundo geral */
--pink-panel: rgba(255, 230, 245, 0.9); /* painéis/caixas */
--pink-selection: #ffb0d6; /* cor da seleção de texto */
--pink-accent: #ff7bb3;    /* acento/link */
--btn-radius: 10px;        /* arredondamento dos botões */
}

/* fundo geral da página */
html, body, #__next, main, .app, .container {
background-color: var(--pink-bg) !important;
background-image: none !important;
color: #111 !important;
}

/* caixas/painéis que costumam ter fundo branco — suaviza com rosa translúcido */
.bg-white, [class*="background"], .panel, .card, section, header, .chat, .chat-container {
background-color: var(--pink-panel) !important;
}

/* links e acentos */
a, a:visited {
color: var(--pink-accent) !important;
text-decoration: underline dotted !important;
}

/* seleção de texto */
*::selection {
background: var(--pink-selection) !important;
color: #000 !important;
}
*::-moz-selection {
background: var(--pink-selection) !important;
color: #000 !important;
}

/* botões — arredondamento e reforço visual leve */
button,
input[type="button"],
input[type="submit"],
[role="button"],
.btn,
.button,
.link-button {
border-radius: var(--btn-radius) !important;
padding: 0.5rem 0.9rem !important;
border: 1px solid rgba(0,0,0,0.06) !important;
background-clip: padding-box !important;
box-shadow: 0 1px 0 rgba(0,0,0,0.03) inset !important;
transition: transform .08s ease, box-shadow .08s ease !important;
}

/* hover / foco dos botões para ficar agradável */
button:hover,
input[type="button"]:hover,
input[type="submit"]:hover,
[role="button"]:hover {
transform: translateY(-1px) !important;
box-shadow: 0 4px 10px rgba(0,0,0,0.06) !important;
}
button:focus,
input[type="button"]:focus,
input[type="submit"]:focus,
[role="button"]:focus {
outline: 3px solid rgba(255,123,179,0.18) !important;
outline-offset: 2px !important;
}

/* mantém contraste nos textos dentro de painéis claros */
.panel, .card, .chat, .chat-container, .prose {
color: #0b0b0b !important;
}

/* pequenas melhorias: inputs e textareas */
input, textarea, .input, .textarea {
border-radius: calc(var(--btn-radius) - 2px) !important;
background-color: rgba(255,255,255,0.95) !important;
border: 1px solid rgba(0,0,0,0.06) !important;
}

/* evita que imagens ou componentes com fundo escuro fiquem ilegíveis */
img[alt], svg {
image-rendering: auto;
}

/* se quiser forçar botões primários com cor rosa (opcional) */
.primary, button.primary, .btn-primary {
background: linear-gradient(180deg, #ff8cc1 0%, #ff6aa6 100%) !important;
color: white !important;
border: 1px solid rgba(0,0,0,0.08) !important;
}
}
